{
  "decisions": [
    {
      "requirement_id": "ETC-101",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior of treating the start condition as fulfilled immediately when no specific sub-conditions are defined is a dynamic runtime behavior that must be observed by executing the OBU with a specific trackside message."
    },
    {
      "requirement_id": "ETC-102",
      "methods": [
        "Test"
      ],
      "rationale": "The interaction between driver acknowledgement and the end condition of the text display requires simulating driver input and observing the display state to verify the correct logic is applied."
    },
    {
      "requirement_id": "ETC-103",
      "methods": [
        "Test"
      ],
      "rationale": "Verifying that the message is not displayed if the end condition is already fulfilled at the moment the start condition is met requires a dynamic test scenario where the timing of conditions is controlled."
    },
    {
      "requirement_id": "ETC-104",
      "methods": [
        "Test"
      ],
      "rationale": "The measurement of the display length relative to the start location is a functional behavior that depends on the OBU's position and state, which must be verified by running the system with specific location-based messages."
    },
    {
      "requirement_id": "ETC-105",
      "methods": [
        "Test"
      ],
      "rationale": "Sending a driver acknowledgement report to the RBC is a communication behavior that can be verified by capturing the outgoing message after simulating the driver's acknowledgement."
    },
    {
      "requirement_id": "ETC-106",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection of a duplicate text message identifier while the previous one is unacknowledged is a state-dependent behavior that must be tested by sending a sequence of messages and observing the OBU's response."
    },
    {
      "requirement_id": "ETC-107",
      "methods": [
        "Test"
      ],
      "rationale": "The specific logic for deleting or keeping Mode Profiles based on the infill reference location and profile type is a complex state transition that requires dynamic testing with various MA infill scenarios."
    },
    {
      "requirement_id": "ETC-108",
      "methods": [
        "Test"
      ],
      "rationale": "The treatment of the Mode Profile start as a temporary EOA and the calculation of the temporary Supervision Limit (SvL) are dynamic safety functions that must be verified by observing the OBU's speed supervision behavior during mode transitions."
    },
    {
      "requirement_id": "ETC-109",
      "methods": [
        "Test"
      ],
      "rationale": "The replacement of stored LX information upon receiving a new message with the same identity is a data management behavior that can be verified by sending sequential LX messages and inspecting the OBU's internal state or subsequent behavior."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-051",
      "methods": [
        "Test"
      ],
      "rationale": "HttpOnly attribute presence and Set-Cookie header usage are verified by inspecting HTTP response headers during a live session."
    },
    {
      "requirement_id": "KDH-052",
      "methods": [
        "Test"
      ],
      "rationale": "The presence and values of the Strict-Transport-Security header are verified by inspecting HTTP response headers."
    },
    {
      "requirement_id": "KDH-053",
      "methods": [
        "Test"
      ],
      "rationale": "File upload validation is verified by submitting files with mismatched extensions and contents to observe rejection behavior."
    },
    {
      "requirement_id": "KDH-054",
      "methods": [
        "Test"
      ],
      "rationale": "Image size validation is verified by uploading images exceeding the defined pixel limits to observe rejection."
    },
    {
      "requirement_id": "KDH-055",
      "methods": [
        "Test"
      ],
      "rationale": "User enumeration prevention is verified by comparing error messages, HTTP codes, and response times for valid and invalid credentials."
    },
    {
      "requirement_id": "KDH-056",
      "methods": [
        "Test"
      ],
      "rationale": "Help Desk permissions are verified by attempting to initiate a reset and attempting to directly change a password to confirm the latter is blocked."
    },
    {
      "requirement_id": "KDH-057",
      "methods": [
        "Test"
      ],
      "rationale": "Session token rotation is verified by authenticating and checking that the old token is invalidated and a new one is issued."
    },
    {
      "requirement_id": "KDH-058",
      "methods": [
        "Test"
      ],
      "rationale": "Session invalidation is verified by attempting to use a session token after logout or expiration to confirm access is denied."
    },
    {
      "requirement_id": "KDH-059",
      "methods": [
        "Test"
      ],
      "rationale": "Re-authentication requirement is verified by attempting sensitive changes after the 5-minute window has elapsed to confirm the block and subsequent success after re-auth."
    },
    {
      "requirement_id": "KDH-060",
      "methods": [
        "Test"
      ],
      "rationale": "Access control is verified by attempting to access resources belonging to other users by modifying request identifiers (IDOR testing)."
    },
    {
      "requirement_id": "KDH-061",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Text alternatives and ARIA labels are verified by inspecting the HTML source code and using accessibility tree tools."
    },
    {
      "requirement_id": "KDH-062",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Programmatic structure and semantics are verified by inspecting the HTML markup for proper use of semantic elements and ARIA roles."
    },
    {
      "requirement_id": "KDH-063",
      "methods": [
        "Test"
      ],
      "rationale": "Orientation independence is verified by rotating the device or resizing the window to ensure content remains usable in both orientations."
    },
    {
      "requirement_id": "KDH-064",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Form field purposes are verified by inspecting the HTML source for the presence of autocomplete attributes."
    },
    {
      "requirement_id": "KDH-065",
      "methods": [
        "Analiz"
      ],
      "rationale": "Contrast ratios are verified by calculating the luminance difference between text and background colors using a contrast checker tool."
    },
    {
      "requirement_id": "KDH-066",
      "methods": [
        "Test"
      ],
      "rationale": "Text resizing is verified by zooming the browser to 200% and observing that content remains readable and functional without loss."
    },
    {
      "requirement_id": "KDH-067",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Use of text instead of images is verified by inspecting the HTML source to ensure information is conveyed via text elements rather than images."
    },
    {
      "requirement_id": "KDH-068",
      "methods": [
        "Test"
      ],
      "rationale": "Spacing adjustments are verified by applying CSS overrides to increase line, paragraph, letter, and word spacing to check for content loss."
    },
    {
      "requirement_id": "KDH-069",
      "methods": [
        "Test"
      ],
      "rationale": "Keyboard operability is verified by navigating and interacting with all portal functions using only the keyboard without time constraints."
    },
    {
      "requirement_id": "KDH-070",
      "methods": [
        "Test"
      ],
      "rationale": "Session timeout warning and extension are verified by waiting 25 minutes of inactivity to observe the dialog, screen reader announcement, and extension button functionality."
    },
    {
      "requirement_id": "KDH-071",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page titles are verified by inspecting the HTML <title> tag of each page to ensure it describes the page content."
    },
    {
      "requirement_id": "KDH-072",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Link purpose clarity is verified by inspecting the link text and associated ARIA labels in the HTML source."
    },
    {
      "requirement_id": "KDH-073",
      "methods": [
        "Test"
      ],
      "rationale": "Focus visibility is verified by navigating with the keyboard and observing that a visible focus indicator appears on each interactive element."
    },
    {
      "requirement_id": "KDH-074",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page language is verified by inspecting the HTML <html> tag for the lang attribute."
    },
    {
      "requirement_id": "KDH-075",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Language of sections is verified by inspecting the HTML source for lang attributes on elements containing text in a different language."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the availability of specific authentication options, which is verified by executing the login flow and observing the presented choices."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to enforce multi-factor or two-factor authentication at AAL2 is verified by attempting logins with valid and invalid factor combinations."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Periodic reauthentication behavior based on inactivity and overall timeouts is verified by simulating user sessions with specific idle and active durations."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of notifications upon account recovery is verified by triggering a recovery event and observing the delivery of the notification."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The distribution of notifications to registered addresses (excluding postal) is verified by triggering a notification event and checking the recipients."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The independence of the VBP session from the e-Devlet assertion validity window is verified by maintaining a VBP session after the e-Devlet assertion expires."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The content of the assertion request, specifically the inclusion of the VBP identifier and cryptographic nonce, is verified by inspecting the network traffic or code implementation."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion audience is verified by attempting to inject an assertion intended for a different relying party and observing the rejection."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The enforcement of the binding process for changing SMS phone numbers is verified by attempting to change the number without completing the required authentication steps."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to bind multiple authenticators is verified by adding more than one authenticator to a single account and confirming their presence."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The required authentication level for binding new authenticators is verified by attempting to bind an authenticator at different AAL levels and observing the system's response."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of independent notifications upon adding an authenticator is verified by adding a new authenticator and checking for the notification via a separate channel."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of confirmation codes after use is verified by submitting a valid code twice and observing the rejection of the second submission."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of assertion signatures is verified by presenting an assertion with an invalid or tampered signature and observing the rejection."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "Replay protection is verified by submitting the same valid assertion twice and observing the rejection of the second instance."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The initiation of federation transactions by VBP as the RP is verified by inspecting the sequence of network requests or the code logic for the federation flow."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of information leakage during proofing is verified by submitting mismatched self-asserted information and observing that the error message does not reveal which specific attribute failed."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of core attributes against authoritative sources or signed evidence is verified by submitting valid and invalid proofing data and observing the acceptance or rejection."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of proofing notifications to validated addresses is verified by completing the IAL2 proofing process and checking for the notification at the specified address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of knowledge-based verification is verified by inspecting the code and configuration to ensure no such mechanism is implemented or enabled."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of email for out-of-band authentication is verified by inspecting the authentication logic and configuration to ensure email is not used as an OOB factor."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "The 5-minute validity window for SMS codes is verified by submitting a correct code after 5 minutes and observing the rejection, and before 5 minutes and observing acceptance."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "The single-use nature of SMS codes is verified by submitting the same valid code twice within the validity period and observing the rejection of the second attempt."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "The non-resetting of failed authentication counts upon generating a new SMS code is verified by failing authentication, requesting a new code, and checking if the failure count persists."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "The absence of additional password composition requirements is verified by setting passwords that meet length and blocklist criteria but lack specific character classes, and observing their acceptance."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik olarak sonlandırılıp sonlandırılmadığı, sistem üzerinde senaryo çalıştırılarak doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediği, olaylar tetiklenerek ve kayıtlar incelenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damplarının UTC cinsinden ve belirlenen ayrıntı düzeyinde üretilip üretilmediği, sistem saatleri ve kayıtlar üzerinden test edilerek doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin algılanıp algılanmadığı ve uyarıların gönderilip gönderilmediği, saldırı senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Parola ve tek kullanımlık kodların ekranda gizlenip gizlenmediği, kullanıcı arayüzü üzerinden girdi vererek ve gözlemleyerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi içinde yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı, işlem akışları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüğü korunarak yapılıp yapılmadığı, ağ trafiği yakalanarak ve man-in-the-middle senaryolarıyla test edilmelidir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz, bozuk veya beklenmedik girdilerin sistem tarafından reddedilip reddedilmediği, çeşitli girdi senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediği ve ayrıntılı loglara erişim yetkisi olan personele gösterilip gösterilmediği, hata senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum süresi uzatılmasının engellenmesi, uyarı gösterimi, taslak kaydı ve veri kaybı olmadan devam etme akışının, sistem üzerinde senaryo çalıştırılarak test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmaması, bot eşiği aşımında etkileşimsiz kanıt istenmesi ve istisna durumlarında nesne tanıma sorgusu gösterilmesinin, bot simülasyonları ve kullanıcı akışlarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzası doğrulanan bildirimle kabul edilmesi, belirsiz durumlarda bekleme ve sorgulama mekanizmasının, KÖA entegrasyon senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirteçlerinde oturumun sınırlı kipte açılması ve kişisel verilerin gizlenmesinin, farklı kimlik doğrulama düzeyleriyle test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulanması, bildirim gönderimi ve ele geçirme kanıtında zorunlu değişiklik akışının, kullanıcı senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilmesi, diğer adımların reddedilmesi ve tek kullanımlık olmasının, zamanlanmış kod senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiği aşımında doğrulayıcının devre dışı bırakılması, hesap kurtarma akışı ve başarılı girişte sayaç sıfırlamanın, tekrarlı başarısız giriş senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 ve AAL3 oturumlarında hareketsizlik sonrası farklı yeniden kimlik doğrulama akışlarının ve oturum sırrı silinmesinin, kullanıcı rolü ve süre senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılması, kullanıcıya bildirim ve SIEM'e olay iletiminin, çoklu oturum senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, içerik imzası ve boyut/sayı sınırlarının denetlenmesi ile ret mesajlarının, çeşitli dosya yükleme senaryolarıyla test edilmesi gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-026",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a functional behavior (rejecting short passwords, accepting long ones) that can be verified by executing the system with specific input lengths."
    },
    {
      "requirement_id": "KDH-027",
      "methods": [
        "Test"
      ],
      "rationale": "The character counting logic for Unicode code points can be verified by providing passwords with specific Unicode characters and observing the system's acceptance or rejection based on length."
    },
    {
      "requirement_id": "KDH-028",
      "methods": [
        "Test"
      ],
      "rationale": "The accessibility of password hints to unauthenticated users can be verified by attempting to access the hint endpoint or UI without authentication."
    },
    {
      "requirement_id": "KDH-029",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The absence of security question prompts is a UI/UX design constraint best verified by inspecting the interface and code to ensure no such fields or logic exist."
    },
    {
      "requirement_id": "KDH-030",
      "methods": [
        "Test"
      ],
      "rationale": "The system's handling of full password submission and verification without truncation can be tested by submitting passwords of varying lengths and checking the verification outcome."
    },
    {
      "requirement_id": "KDH-031",
      "methods": [
        "Test"
      ],
      "rationale": "The blocklist comparison functionality can be verified by attempting to set passwords that are known to be on the blocklist and observing the rejection."
    },
    {
      "requirement_id": "KDH-032",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to compare the entire password rather than substrings can be tested by using passwords that contain blocklisted words as substrings but are not themselves on the blocklist."
    },
    {
      "requirement_id": "KDH-033",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection message and requirement to select a different password can be verified by submitting a blocklisted password and observing the system's response."
    },
    {
      "requirement_id": "KDH-034",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The presence of guidance on choosing strong passwords, especially after rejection, is a UI feature that can be demonstrated by navigating to the relevant screens."
    },
    {
      "requirement_id": "KDH-035",
      "methods": [
        "Test"
      ],
      "rationale": "The compatibility with password managers and autofill can be verified by using a browser's autofill feature or a password manager extension to fill in the password fields."
    },
    {
      "requirement_id": "KDH-036",
      "methods": [
        "Test"
      ],
      "rationale": "The account recovery mechanisms can be verified by simulating the recovery process using the specified methods (recovery codes, authenticator, identity proofing)."
    },
    {
      "requirement_id": "KDH-037",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of an authenticator after 50 consecutive failed attempts can be verified by performing 50 failed logins and then attempting a successful login."
    },
    {
      "requirement_id": "KDH-038",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of multiple authenticators involved in failed attempts can be verified by simulating failed multi-factor authentication attempts until the threshold is reached."
    },
    {
      "requirement_id": "KDH-039",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to re-bind a disabled authenticator can be verified by attempting to use a disabled authenticator and observing the system's request for re-binding."
    },
    {
      "requirement_id": "KDH-040",
      "methods": [
