{
  "test_cases": [
    {
      "id": "TC-076-01",
      "title": "OBU reads next main signal balise group and ignores subsequent loop infill",
      "covers": [
        "ETC-076"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is in Level 1 operation. The OBU has read a main signal balise group (BG1) indicating the next main signal balise group (BG2). The loop infill unit is active and transmitting infill information for BG2.",
      "test_inputs": "Train moves from BG1 towards BG2. Loop infill data for BG2 is transmitted. OBU reads BG2.",
      "assumptions": "The loop infill unit continues to transmit data for a short period after the OBU reads BG2 to simulate the 'further' information condition.",
      "steps": [
        {
          "no": 1,
          "action": "Move the train so that the OBU reads the next main signal balise group (BG2).",
          "expected": "The OBU processes the data from BG2 and updates its internal state to reflect the new main signal."
        },
        {
          "no": 2,
          "action": "Ensure the loop infill unit transmits additional infill information related to BG2 after the OBU has read BG2.",
          "expected": "The OBU ignores the received loop infill information. The OBU's internal state and movement authority remain consistent with the data from BG2 and are not modified by the loop infill data."
        }
      ]
    },
    {
      "id": "TC-076-02",
      "title": "OBU detects missed next main signal balise group and ignores subsequent loop infill",
      "covers": [
        "ETC-076"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "The OBU is in Level 1 operation. The OBU has read a main signal balise group (BG1) indicating the next main signal balise group (BG2). The loop infill unit is active and transmitting infill information for BG2. The train is positioned such that it will pass BG2 without reading it (e.g., due to a fault or specific test setup).",
      "test_inputs": "Train moves past BG2 without reading it. Loop infill data for BG2 is transmitted after the miss is detected.",
      "assumptions": "The OBU has a mechanism to detect that the expected balise group was missed (e.g., based on distance traveled or timeout).",
      "steps": [
        {
          "no": 1,
          "action": "Move the train past the location of the next main signal balise group (BG2) without the OBU reading it, triggering the 'missed' detection logic.",
          "expected": "The OBU detects that the next main signal balise group was missed and initiates the appropriate safety reaction (e.g., braking or state change as per other requirements, but specifically here we focus on the infill handling)."
        },
        {
          "no": 2,
          "action": "Ensure the loop infill unit transmits additional infill information related to BG2 after the OBU has detected the miss.",
          "expected": "The OBU ignores the received loop infill information. The OBU does not use the loop infill data to update its movement authority or signal state."
        }
      ]
    }
  ]
}

