{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Disabled authenticator requires re-binding before use",
      "covers": [
        "KDH-039"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists. An authenticator bound to this account has been disabled due to reaching the failed-attempt threshold defined in VBP SDD §14.",
      "test_inputs": "Credentials for the disabled authenticator.",
      "assumptions": "The failed-attempt threshold is defined in VBP SDD §14. The re-binding process follows NIST SP 800-63B-4 §4.1.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to authenticate using the disabled authenticator without re-binding.",
          "expected": "Authentication fails. The system indicates that the authenticator is disabled and requires re-binding."
        },
        {
          "no": 2,
          "action": "Initiate the re-binding process for the disabled authenticator to the company representative account as per NIST SP 800-63B-4 §4.1.",
          "expected": "The re-binding process completes successfully. The authenticator status changes to active/bound."
        },
        {
          "no": 3,
          "action": "Attempt to authenticate using the re-bound authenticator.",
          "expected": "Authentication succeeds. The user is granted access."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Re-binding is mandatory after threshold breach",
      "covers": [
        "KDH-039"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists. An authenticator is bound to this account.",
      "test_inputs": "Invalid credentials to trigger the failed-attempt threshold.",
      "assumptions": "The failed-attempt threshold is defined in VBP SDD §14.",
      "steps": [
        {
          "no": 1,
          "action": "Perform consecutive failed authentication attempts using the authenticator until the threshold defined in VBP SDD §14 is reached.",
          "expected": "The authenticator is disabled by the system."
        },
        {
          "no": 2,
          "action": "Attempt to use the authenticator for authentication immediately after it is disabled, without performing any re-binding steps.",
          "expected": "Authentication is rejected. The system explicitly requires re-binding to the company representative account before the authenticator can be used."
        }
      ]
    }
  ]
}

