{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Multiple authenticators disabled upon reaching failure threshold",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with both password and a second factor (e.g., OTP) enabled. The failure threshold is defined in VBP SDD §14 (assumed to be 5 for this test).",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for consecutive failed attempts is 5, as per VBP SDD §14. The system tracks failures per authenticator and per account.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the correct username, an incorrect password, and an incorrect second factor code.",
          "expected": "Authentication fails. The system records a failed attempt for both the password and the second factor authenticators."
        },
        {
          "no": 2,
          "action": "Repeat the login attempt with incorrect credentials for the remaining number of attempts required to reach the threshold (e.g., 4 more times if threshold is 5).",
          "expected": "Each attempt fails. The system continues to record failures for both authenticators."
        },
        {
          "no": 3,
          "action": "Check the status of the password and second factor authenticators for the account.",
          "expected": "Both the password and the second factor authenticators are disabled for the account, as specified in NIST SP 800-63B-4 §3.2.2."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Single authenticator failure does not disable other authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists with both password and a second factor enabled. The failure threshold is 5.",
      "test_inputs": "Valid username, incorrect password, correct second factor code.",
      "assumptions": "The system only disables authenticators involved in the failed attempts. If only the password is wrong, only the password authenticator is considered for disabling if the threshold is reached for that specific authenticator, but the requirement states 'if more than one authenticator is involved... disable all'. This test verifies that if only one is involved in the failure pattern, the other remains active or the logic applies only when multiple are involved in the *consecutive failed attempts* leading to the threshold. However, the requirement says 'If more than one authenticator is involved in consecutive failed authentication attempts...'. This implies the failure event involves multiple. Let's interpret 'involved' as the authenticators that were checked and failed. If I enter wrong password but correct OTP, the password fails, OTP succeeds? No, usually MFA requires both. If password fails, the process stops. So 'involved' likely means the set of authenticators that were part of the authentication flow that failed. If the flow is Password -> OTP, and Password fails, only Password is 'involved' in the failure. If Password succeeds and OTP fails, only OTP is involved. The requirement triggers when *more than one* is involved. This is tricky. Let's assume the requirement means: If the account reaches the threshold of failed attempts, and during those attempts, multiple authenticators were the ones being tested and failing (or the system considers the combination), then disable all. A safer interpretation for testing: The requirement specifically targets the case where the failure involves multiple authenticators. If I only fail the password, the OTP is not 'involved' in the failure. So, if I reach the threshold failing only the password, the OTP should NOT be disabled. This is a valid negative test for the 'more than one' condition.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the correct username, an incorrect password, and a correct second factor code (if the system allows entering OTP before password check, or if it checks password first and fails, the OTP is not 'involved' in the failure). Let's assume standard flow: Password first. If password fails, OTP is not requested. Thus, only Password is involved in the failure.",
          "expected": "Authentication fails. Only the password authenticator is recorded as failed."
        },
        {
          "no": 2,
          "action": "Repeat the login attempt with incorrect password until the threshold is reached.",
          "expected": "The password authenticator is disabled. The second factor authenticator remains enabled."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Verification of disabled authenticator status in UI",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "The account has reached the failure threshold with multiple authenticators involved, and they have been disabled.",
      "test_inputs": "Valid username.",
      "assumptions": "The user interface displays the status of authenticators or provides a specific error message indicating which authenticators are disabled.",
      "steps": [
        {
          "no": 1,
          "action": "Navigate to the account security settings or login page for the affected account.",
          "expected": "The system indicates that the password and second factor authenticators are disabled or requires re-binding/recovery, consistent with the disabling action."
        }
      ]
    }
  ]
}

